contract InvMutTest {
    C c;
    address distributor;

    constructor(C _c) {
        c = _c;
        // record the initial distributor from the contract's public variable
        distributor = c.rewardDistributor();
    }

    // We will call notifyRewardAmount on c. Provide the reward token address and amount.
    // The function must be called from the distributor address. In this testing setup
    // msg.sender for c calls will be this contract, so we require distributor == address(this)
    // otherwise notifyRewardAmount should revert with "not distributor". We capture that.
    function run(address rewardToken, uint256 amount) public payable {
        require(rewardToken != address(0), true);

        // Read periodFinish before the call (may be zero if token unknown)
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = IERC20(rewardToken).balanceOf(address(c));

        bool reverted;
        // Attempt call; it requires msg.sender == rewardDistributor in c, so this test only proves
        // the invariant in the case the distributor equals this contract. If not, the call must revert
        // with "not distributor" and we assert that when reverted, nothing transferred to c.
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBalance = IERC20(rewardToken).balanceOf(address(c));

        // General rule:
        // - If call succeeded (not reverted) then afterFinish >= block.timestamp and afterBalance - beforeBalance == amount.
        // - If call reverted then afterBalance == beforeBalance (no transfer happened).
        // We encode this as a single assert combining both cases.
        assert(
            (!reverted && uint256(afterFinish) >= block.timestamp && afterBalance - beforeBalance == amount)
            || (reverted && afterBalance == beforeBalance)
        );
    }

    // Allow contract to receive tokens if needed
    receive() external payable {}
}

