        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBal = IERC20(rewardToken).balanceOf(address(c));

        // General rule combining both outcomes:
        // If the call reverted then the contract's token balance did not change.
        // If it succeeded then the contract's token balance increased exactly by `amount`
