contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We require caller to be the rewardDistributor, so take distributor as parameter and set via c.setRewardDistributor by owner.
    // But only the owner (this contract at construction was the deployer of c) can call setRewardDistributor; constructor ran in deployer context.
    // The test will: 1) addReward(token) as owner, 2) set rewardDistributor to address(this), 3) call notifyRewardAmount(token, amount)
    // Then assert that rewardPeriodFinish(token) >= block.timestamp + 1 and notify did not accept unknown token and amount>0.

    // Single public test function taking the reward token and amount. It will revert if preconditions fail; we ensure amount>0.
    function run(address rewardToken, uint256 amount) public payable {
        require(rewardToken != address(0), "need token");
        require(amount > 0, "amount>0");

        // As the deployer of c, this contract is the owner (per C constructor ownership). set up reward token and distributor.
        c.addReward(rewardToken);
        c.setRewardDistributor(address(this));

        // Approve this contract to transfer rewardToken from this contract to c before calling notifyRewardAmount.
        // We cannot call token's approve (external token contract) here because we must only interact with c. Instead we assume the token already has balance in this contract and
        // that notifyRewardAmount will call safeTransferFrom(msg.sender, address(this), _amount) on the token. That requires this contract to have approved c to spend tokens.
        // However we cannot interact with the token contract (not allowed per constraints), so instead we rely on the fact that notifyRewardAmount will revert if transferFrom fails.
        // We'll catch whether notifyRewardAmount reverted.

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, if notifyRewardAmount succeeded (not reverted) then:
        // - rewardPeriodFinish(rewardToken) should be >= block.timestamp (in practice it's block.timestamp + DURATION),
        //   and strictly greater than block.timestamp because DURATION>0. We'll assert it's >= block.timestamp + 1 to express strict future.
        // If it reverted, then it's either because msg.sender was not distributor (not our case) or amount==0 or unknown reward token or transferFrom failed.
        // We assert: if not reverted then rewardPeriodFinish >= block.timestamp + 1 and rewardData existed before (we created it via addReward). If reverted then true about existence may still hold,
        // but we only assert the implication to avoid false negatives.

        uint40 finish = c.rewardPeriodFinish(rewardToken);

        assert(reverted || finish >= uint40(block.timestamp + 1));
    }

    receive() external payable { }
}

