contract InvMutTest {
    C c;
    IERC20 tok;

    constructor(C _c) {
        c = _c;
        tok = c.stakingToken();
    }

    // single public test entry
    // params: staker (the account that will be used as msg.sender in stakeFor), amount to stake
    // Note: when InvMutTest calls c.stakeFor, msg.sender == address(this)
    function run(address stakerPlaceholder, uint256 amount) public payable {
        require(amount > 0, "need positive amount");

        // Approve and mint behavior: we cannot mint tokens or change external accounts here.
        // But we can work with the test contract's own token balance. Ensure this contract has enough tokens
        // by requiring its balance is >= amount (checker will arrange token balances when proving).
        require(tok.balanceOf(address(this)) >= amount, "test contract lacks tokens");

        // Read before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeCTokenBal = tok.balanceOf(address(c));

        // Approve c to transfer staking tokens from this test contract
        // This is a state-changing call on the token, but tokens are external; allowed as it's a public call on IERC20
        tok.approve(address(c), amount);

        // Attempt to stakeFor: note stakeFor takes (address _for, uint256 _amount) and uses msg.sender as the transferFrom caller.
        bool reverted;
        try c.stakeFor(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(address(this));
        uint256 afterCTokenBal = tok.balanceOf(address(c));

        // General rule to assert:
        // If stakeFor did not revert then:
        //  - totalSupply increased by exactly amount
        //  - staker's balance increased by exactly amount
        //  - contract's token balance increased by at least amount (transfer may combine with prior tokens)
        // If stakeFor reverted then no state change: totals and balances unchanged, and contract token balance unchanged.
        assert(
            reverted
                ? (afterTotal == beforeTotal && afterBalance == beforeBalance && afterCTokenBal == beforeCTokenBal)
                : (afterTotal == beforeTotal + amount && afterBalance == beforeBalance + amount && afterCTokenBal >= beforeCTokenBal + amount)
        );
    }

    // allow receiving ETH if needed by token or other calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    IERC20 rewardToken;

    constructor(C _c) {
        c = _c;
        // rewardToken will be read later from parameters; cannot call c.rewardTokens() safely here
    }

    // params:
    // - distributor: address that will call notifyRewardAmount (must match c.rewardDistributor() to avoid immediate revert)
    // - _rewardsToken: token address to notify
    // - amount: amount to notify and transfer from distributor to c
    function run(address distributor, address _rewardsToken, uint256 amount) public payable {
        require(_rewardsToken != address(0), "bad token");

        // Observe pre-state via public getters
        uint40 beforeFinish = c.rewardPeriodFinish(_rewardsToken);
        uint256 beforeContractBal = IERC20(_rewardsToken).balanceOf(address(c));

        // Ensure this test contract has approved the distributor to move tokens on its behalf is impossible here.
        // Instead, the test will attempt the call as if msg.sender==distributor by making the distributor param equal
        // to address(this) or not; but we must invoke c.notifyRewardAmount as this contract (msg.sender == address(this)).
        // The contract requires msg.sender == rewardDistributor. So we expect it to revert unless distributor==address(this)

        // To match the requirement that calls that change c's state are top-level, do the call directly with try/catch.
        bool reverted;
        try c.notifyRewardAmount(_rewardsToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint40 afterFinish = c.rewardPeriodFinish(_rewardsToken);
        uint256 afterContractBal = IERC20(_rewardsToken).balanceOf(address(c));

        // General rule:
        // If the call reverted then public observable reward period finish and token balance of c must be unchanged.
        // If it didn't revert then periodFinish must have advanced to > beforeFinish and contract token balance must have increased by at least amount.
        assert(
            reverted
                ? (afterFinish == beforeFinish && afterContractBal == beforeContractBal)
                : (uint256(afterFinish) > uint256(beforeFinish) && afterContractBal >= beforeContractBal + amount)
        );
    }

    receive() external payable {}
}

