contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for the property test
    function run(address staker, uint256 stakeAmount, uint256 withdrawAmount, bool claim) public payable {
        require(staker != address(0) && withdrawAmount <= type(uint256).max);

        // Preconditions: ensure a reward token exists so updateReward loops run deterministically
        // addReward is onlyOwner; the deploying test contract is owner (per C constructor uses msg.sender)
        // create a dummy reward token address by using the c contract address (must be an address)
        // We try to add a reward token if possible; if it reverts (not owner) we continue
        bool added = false;
        try c.addReward(address(c)) {
            added = true;
        } catch {}

        // Snapshot totalSupply before any actions
        uint256 totalBefore = c.totalSupply();

        // Try to perform stakeFor: this call will likely revert because this contract has no stakingToken allowance/balance
        // We instead call stakeFor through try/catch; the goal is to reach withdraw and observe behavior.
        bool stakeReverted;
        try c.stakeFor(staker, stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // Snapshot totalSupply after stake attempt
        uint256 totalAfterStake = c.totalSupply();

        // Now attempt to withdraw for staker via calling withdraw on c as if staker called it: but msg.sender will be this contract
        // We cannot change msg.sender for calls, so call migrate flow if migrator set to this contract would allow withdraw; instead we directly call withdraw on c which acts on msg.sender
        // To exercise withdraw, we attempt to call withdraw(withdrawAmount, claim) from this contract.
        bool withdrawReverted;
        try c.withdraw(withdrawAmount, claim) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Snapshot totalSupply after withdraw attempt
        uint256 totalAfter = c.totalSupply();

        // General invariant to assert:
        // If withdraw succeeded (did not revert), then totalAfter <= totalAfterStake and totalAfterStake <= totalBefore + stakeAmount
        // We avoid arithmetic that can underflow by using only non-subtractive comparisons.
        // Also ensure that totalSupply never increased solely due to withdraw: totalAfter <= totalAfterStake

        assert((withdrawReverted && (totalAfter == totalAfterStake)) || (!withdrawReverted && totalAfter <= totalAfterStake));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for the property test
    function run(uint256 stakeAmount, uint256 withdrawAmount, bool claim) public payable {
        require(withdrawAmount <= type(uint256).max);

        // Ensure there's at least one reward token to make updateReward loops execute deterministically.
        // addReward is onlyOwner; the deployer of C is this contract, so this should succeed unless already added.
        // We ignore failure if already added.
        try c.addReward(address(c)) {} catch {}

        // Snapshot totalSupply before any actions
        uint256 totalBefore = c.totalSupply();

        // Attempt to stake (may revert due to missing allowance/balance). We don't require success.
        bool stakeReverted;
        try c.stakeFor(address(this), stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // Snapshot after stake attempt
        uint256 totalAfterStake = c.totalSupply();

        // Attempt withdraw from this contract (msg.sender == this). Capture whether it reverted.
        bool withdrawReverted;
        try c.withdraw(withdrawAmount, claim) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Snapshot after withdraw attempt
        uint256 totalAfter = c.totalSupply();

        // Assert: If withdraw succeeded then totalSupply did not increase compared to before the withdraw attempt
        // (i.e., totalAfter <= totalAfterStake). If withdraw reverted, we allow totalAfter unchanged relative to totalAfterStake.
        assert((!withdrawReverted && totalAfter <= totalAfterStake) || (withdrawReverted && totalAfter == totalAfterStake));
    }

    receive() external payable {}
}

