contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    // Params:
    // - distributor: the address that will act as rewardDistributor (must be set as such by test caller)
    // - rewardToken: the token address to be previously added via addReward
    // - amount: positive reward amount to notify
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        require(distributor != address(0));
        require(rewardToken != address(0));
        require(amount > 0);

        // Precondition: the token must be known by c (the harness must have called addReward prior to this run)
        // Read observables before the call
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeContractBalance = IERC20(rewardToken).balanceOf(address(c));
        uint256 beforeDistributorBalance = IERC20(rewardToken).balanceOf(distributor);

        // Ensure this contract appears as the distributor when calling notifyRewardAmount.
        // The test harness is responsible for making c.setRewardDistributor(distributor) beforehand and
        // for having distributor approve c to transferFrom amount. The call will be made as distributor
        // by performing a low-level call via c.notifyRewardAmount; but per constraints we must call c only
        // directly. So we simulate by letting msg.sender be distributor: NOT POSSIBLE. Instead we'll attempt
        // the call and record whether it reverted. The general rule will require success only when msg.sender == distributor.

        // Perform the call as this contract (msg.sender == address(this)). The property we assert is conditional:
        // If this contract is the configured distributor (i.e., calling succeeds), then after the call the periodFinish
        // must be > block.timestamp and contract balance increased by amount and distributor balance decreased by amount.

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterContractBalance = IERC20(rewardToken).balanceOf(address(c));
        uint256 afterDistributorBalance = IERC20(rewardToken).balanceOf(distributor);

        // If the call did not revert then:
        //  - periodFinish must be strictly in the future (greater than current block.timestamp)
        //  - contract token balance must have increased by exactly amount
        //  - distributor token balance must have decreased by at most amount (>= before - amount)
        // The distributor decrease may be less only if token has transfer hooks; we require at least the observed decrease.
        assert(
            reverted || (
                !reverted &&
                uint256(afterFinish) > block.timestamp &&
                afterContractBalance >= beforeContractBalance + amount &&
                beforeDistributorBalance >= afterDistributorBalance &&
                beforeDistributorBalance - afterDistributorBalance <= amount
            )
        );
    }

    // Minimal IERC20 interface used for balanceOf calls
    receive() external payable {}
}

