        // But we cannot interact with an ERC20 token type here (can't deploy or manipulate token contract). The checker will supply
        // arbitrary rewardToken addresses; we cannot guarantee transfer will succeed. Therefore instead we assert a general rule
        // that is independent of the ERC20 transfer success: when notifyRewardAmount is called by rewardDistributor, the
        // contract's reported rewardPeriodFinish for that token is at least block.timestamp + C.DURATION().
        // However DURATION is a public constant in C, so we can observe it via c.DURATION().

        // Read before-values
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 duration = c.DURATION();

        // Call notifyRewardAmount as the designated distributor (this contract)
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 nowPlusDurLowerBound = block.timestamp + duration;

        // General rule: if notifyRewardAmount did NOT revert, then afterFinish >= now + DURATION and contract's recorded periodFinish changed from before
        // If it reverted, then nothing is required; but to make the assertion meaningful we assert: either it reverted, or afterFinish >= now+duration
        assert(reverted || (uint256(afterFinish) >= nowPlusDurLowerBound));
    }

    receive() external payable {}
}

