contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take distributor, rewardToken, and amount as inputs. The function will
    // first ensure the reward token is registered by calling addReward as owner
    // (the deployer of C is the owner; here InvMutTest is msg.sender for calls).
    // Then it will attempt to call notifyRewardAmount from the given distributor
    // by calling setRewardDistributor (onlyOwner) to set distributor, and
    // finally calling notifyRewardAmount from that distributor address via
    // low-level call emulation: since msg.sender for calls from this contract
    // is always InvMutTest, we instead set rewardDistributor to this test
    // contract and then perform the call, or set to provided distributor and
    // perform the call and capture whether it reverts. However we cannot change
    // msg.sender to an arbitrary address, so to test both success and revert
    // paths we will: (1) addReward, (2) set rewardDistributor to address(this),
    // (3) call notifyRewardAmount (this will succeed if preconditions hold),
    // and (4) capture whether an attempted notifyRewardAmount from the input
    // distributor would revert by trying a low-level call via the test
    // contract to c with data encoded for notifyRewardAmount and using
    // address(callFrom). But since the InvMutTest cannot send calls as other
    // addresses, instead we assert the invariant that when notifyRewardAmount
    // is successfully called by the configured distributor, rewardPeriodFinish
    // is >= block.timestamp.

    // The single public function performing the property test.
    function run(address rewardToken, uint256 amount) public payable {
        require(rewardToken != address(0), "need reward token");
        require(amount > 0, "need positive amount");

        // Ensure reward token is registered. addReward is onlyOwner; the owner
        // of c is the deployer of c (per constructor of C). The InvMutTest
        // contract was passed that c instance in its constructor by the
        // harness; we are not guaranteed to be owner. To be safe, we try the
        // call and ignore revert: if we are not owner, addReward will revert
        // and we cannot proceed; but property must hold for all inputs and be
        // reachable. So instead we first try to addReward and if it reverts we
        // stop early by asserting a condition that relates that revert to the
        // inability to proceed. We detect revert using try/catch style via low-level call.

        // Try to addReward: must be top-level state-changing call.
        bool addReverted;
        bytes memory addData = abi.encodeWithSelector(C.addReward.selector, rewardToken);
        (bool okAdd, ) = address(c).call(addData);
        addReverted = !okAdd;

        // If addReward reverted, we cannot reliably set up the reward token.
        // In that case the only general rule we can assert is that calling
        // rewardPeriodFinish for that token returns 0 (unregistered) or some
        // value, but we need a non-trivial property. We'll require that if
        // addReward reverted then rewardData.lastUpdateTime was already nonzero
        // (i.e., token already existed) — observable via rewardPeriodFinish != 0
        // is not strictly equivalent, but rewardPeriodFinish is set to block.timestamp
        // in addReward. So assert: if addReward reverted then rewardPeriodFinish != 0.

        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        // Now ensure this contract is the rewardDistributor so we can call
        // notifyRewardAmount successfully (if preconditions hold). Only owner
        // can call setRewardDistributor, so similarly it might revert. Try it.
        bytes memory setDistData = abi.encodeWithSelector(C.setRewardDistributor.selector, address(this));
        (bool okSet, ) = address(c).call(setDistData);
        bool setReverted = !okSet;

        // Attempt to call notifyRewardAmount as this contract (should succeed
        // only if rewardDistributor == address(this) and token registered and amount>0).
        bool notifyReverted;
        bytes memory notifyData = abi.encodeWithSelector(C.notifyRewardAmount.selector, rewardToken, amount);
        (bool okNotify, ) = address(c).call{value: 0}(notifyData);
        notifyReverted = !okNotify;

        // Read rewardPeriodFinish after the attempted notify (it is a view).
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // General rule asserted:
        // If notifyRewardAmount call succeeded (notifyReverted == false) then
        // the reward period finish for that token must be >= current block.timestamp.
        // We observe block.timestamp via comparing to before/after values: since
        // afterFinish is expected to be set to block.timestamp + DURATION, it must be >= beforeFinish
        // and >= current block.timestamp. We can't read block.timestamp here
        // directly in the assertion in a model checker, but comparing to beforeFinish
        // helps: when notify succeeds, afterFinish must be >= beforeFinish and != 0.

        // We assert the main invariant: successful notify implies afterFinish >= beforeFinish and afterFinish != 0.
        assert(notifyReverted || (afterFinish >= beforeFinish && afterFinish != 0));
    }

    receive() external payable {}
}

