    // single public entry with parameters controlling stakeFor
    function run(address staker, uint256 approveAmount, uint256 stakeAmount) public payable {
        // Preconditions for meaningful test: staker must not be zero and stakeAmount > 0
        require(staker != address(0) && stakeAmount > 0, true);

        // The InvMutTest contract will act as msg.sender when interacting with token and c.
        // First, ensure this contract has enough stakingToken to transferFrom by simulating
        // that 'staker' has approved this contract. We cannot mint tokens or change external accounts,
        // but we can only rely on public surface. So we require that the token.allowance and balance
        // relationships are such that transferFrom may succeed when staker==address(this) OR
        // when allowance is sufficiently large. To keep the test executable, if staker != address(this)
        // we conservatively attempt the call and detect revert.

        // Record before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(staker);
        uint256 beforeContractTokenBal = address(c).balance; // ETH balance of c
        // also read token balance of contract
        uint256 beforeTokenBal = token.balanceOf(address(c));

        // Try to perform stakeFor from this contract as if msg.sender calls stakeFor.
        // We need to ensure transferFrom will succeed if allowed. We attempt to call stakeFor and catch revert.
        bool reverted;
        // If staker != address(this), stakeFor will stake for _for but transferFrom uses msg.sender,
        // which will be this contract. So we don't require any approval from external staker.
        // But token.transferFrom will pull from msg.sender, i.e., this contract. So require this contract
        // has sufficient token balance and allowance is irrelevant. We cannot mint tokens, so in many
        // configurations the call will revert; we capture that.

        // To give this contract tokens, if staker==address(this) the token.balanceOf(this) may be >0.
        // The checker will try to find inputs that reach assert; it's acceptable if some inputs revert as long
        // as some execution reaches the assert.

        try c.stakeFor(staker, stakeAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(staker);
        uint256 afterTokenBal = token.balanceOf(address(c));

