        // and the staker's balance increased by stakeAmount, and the token balance held by the
        // contract is at least increased by stakeAmount (safeTransferFrom moved tokens in).
        // If stakeFor reverted then no guarantees — but assert must be general. So assert the implication.
        assert(reverted || (afterTotal == beforeTotal + stakeAmount && afterBal == beforeBal + stakeAmount && afterTokenBal >= beforeTokenBal + stakeAmount));
    }

    receive() external payable {}
}

