        }

        uint256 afterTokenBalance;
        bytes memory retAfter;
        (bool okAfter, bytes memory retAfterRaw) = _rewardsToken.call(sig);
        retAfter = retAfterRaw;
        if (okAfter && retAfter.length >= 32) {
            afterTokenBalance = abi.decode(retAfter, (uint256));
        } else {
            afterTokenBalance = 0;
        }

        uint40 afterFinish = c.rewardPeriodFinish(_rewardsToken);

        // Assert the general invariant: either the call reverted and nothing observable changed,
        // or it succeeded and the contract's token balance increased by exactly _amount and periodFinish did not decrease.
        assert(
            (didRevert && afterTokenBalance == beforeTokenBalance && afterFinish == beforeFinish)
            ||
            (!didRevert && afterTokenBalance == beforeTokenBalance + _amount && uint256(afterFinish) >= uint256(beforeFinish))
        );
    }

    receive() external payable {}
}
